/// `Icon { name: "play", class: "size-5" }`
#[component]
pub fn Icon(name: &'static str, #[props(into, default)] class: String, #[props(default = false)] filled: bool) -> Element {
    let fill = if filled { "currentColor" } else { "none" };
    let svg = format!(
        r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="{fill}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:100%;height:100%">{}</svg>"#,
        svg_body(name)
    );
    let cls = if class.is_empty() { "size-4".to_string() } else { class };
    rsx! {
        span { class: "inline-flex shrink-0 {cls}", dangerous_inner_html: "{svg}" }
    }
}

/// Das MAZ-Logo (eigene Wortmarke)
#[component]
pub fn MazLogo(#[props(into, default)] class: String) -> Element {
    let cls = if class.is_empty() { "size-8 text-[11px]".to_string() } else { class };
    rsx! {
        div { class: "relative grid place-items-center rounded-xl maz-gradient-bg text-white font-black shadow-lg shadow-black/30 {cls}",
            span { class: "tracking-tighter leading-none", "MAZ" }
        }
    }
}
